import sys
import bisect
from itertools import permutations

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    M = int(input[ptr])
    ptr += 1
    w = list(map(int, input[ptr:ptr+N]))
    ptr += N
    bridge = []
    for _ in range(M):
        l = int(input[ptr])
        v = int(input[ptr+1])
        bridge.append((v, l))
        ptr += 2
    # Sort bridge by v
    bridge.sort()
    sorted_v = [v for v, l in bridge]
    # Create prefix_max_l
    prefix_max_l = [0] * M
    if M > 0:
        prefix_max_l[0] = bridge[0][1]
        for i in range(1, M):
            prefix_max_l[i] = max(prefix_max_l[i-1], bridge[i][1])
    min_total = float('inf')
    valid = False
    for perm in permutations(w):
        consecutive_sums = []
        for i in range(N):
            current_sum = 0
            for j in range(i, N):
                current_sum += perm[j]
                consecutive_sums.append(current_sum)
        current_max_l = 0
        for S in consecutive_sums:
            idx = bisect.bisect_left(sorted_v, S)
            if idx > 0:
                current_max_l = max(current_max_l, prefix_max_l[idx-1])
        if current_max_l == 0:
            valid = True
            break
        else:
            if current_max_l < min_total:
                min_total = current_max_l
    if valid:
        print(0)
    else:
        if min_total == float('inf'):
            print(-1)
        else:
            print(min_total)

