    bridge_parts = []
    for _ in range(M):
        l = int(data[idx])
        v = int(data[idx+1])
        bridge_parts.append((l, v))
        idx += 2

    min_total = float('inf')

    for perm in permutations(range(N)):
        current_required = []
        for j in range(N):
            for k in range(j, N):
                group_sum = sum(w[perm[i]] for i in range(j, k+1))
                max_l = 0
                for l, v in bridge_parts:
                    if group_sum > v:
                        if l > max_l:
                            max_l = l
                if max_l > 0:
                    current_required.append(max_l)
        if not current_required:
            current_min = 0
        else:
            current_min = max(current_required)
        if current_min < min_total:
            min_total = current_min

    if min_total == float('inf'):
        print(-1)
    else:
        print(min_total)

