import sys
from collections import deque

def is_palindrome(s):
    return s == s[::-1]

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    costs = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append(s)
        costs.append(c)
        idx += 2

    max_len = 100  # Adjust based on problem constraints
    cost_dict = {}
    queue = deque()

    # Initialize with each string
    for i in range(N):
        s = strings[i]
        if s not in cost_dict or costs[i] < cost_dict.get(s, float('inf')):
            cost_dict[s] = costs[i]
            queue.append(s)

    # BFS to generate all possible strings up to max_len
    while queue:
        current = queue.popleft()
        for i in range(N):
            new_s = current + strings[i]
            new_len = len(new_s)
            if new_len > max_len:
                continue
            new_cost = cost_dict[current] + costs[i]
            if new_s not in cost_dict or new_cost < cost_dict.get(new_s, float('inf')):
                cost_dict[new_s] = new_cost
                queue.append(new_s)

    min_cost = float('inf')
    for s in cost_dict:
        if is_palindrome(s):
            if cost_dict[s] < min_cost:
                min_cost = cost_dict[s]
        rev_s = s[::-1]
        if rev_s in cost_dict:
            total_cost = cost_dict[s] + cost_dict[rev_s]
            if total_cost < min_cost:
                min_cost = total_cost

    print(min_cost if min_cost != float('inf') else -1)

