import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    strings = []
    index = 1
    for _ in range(n):
        s = data[index]
        c = int(data[index + 1])
        strings.append((s, c))
        index += 2

    dp = {}
    for s, c in strings:
        if s not in dp or c < dp[s]:
            dp[s] = c

    queue = deque(dp.keys())

    while queue:
        current = queue.popleft()
        for s, c in strings:
            new_s = current + s
            new_cost = dp[current] + c
            if new_s not in dp or new_cost < dp[new_s]:
                dp[new_s] = new_cost
                queue.append(new_s)

    min_cost = float('inf')
    for s in dp:
        if s == s[::-1]:
            if dp[s] < min_cost:
                min_cost = dp[s]
        else:
            rev_s = s[::-1]
            if rev_s in dp:
                total = dp[s] + dp[rev_s]
                if total < min_cost:
                    min_cost = total

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

