import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    X = int(input[1])
    D = int(input[2])

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    abs_D = abs(D)
    ranges = defaultdict(list)

    for m in range(N + 1):
        min_k = m * (m - 1) // 2
        T_m = m * (N - m)
        a_m = X * m + D * min_k
        r = a_m % abs_D
        k_m = (a_m - r) // D
        start = k_m
        end = k_m + T_m
        ranges[r].append((start, end))

    total = 0
    for r in ranges:
        intervals = ranges[r]
        intervals.sort()
        merged = []
        for s, e in intervals:
            if not merged:
                merged.append([s, e])
            else:
                last_s, last_e = merged[-1]
                if s > last_e:
                    merged.append([s, e])
                else:
                    merged[-1][1] = max(last_e, e)
        for s, e in merged:
            total += e - s + 1

    print(total)

