def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    X = int(input[1])
    D = int(input[2])

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    residue_intervals = defaultdict(list)
    D_abs = abs(D)

    for m in range(N + 1):
        s_min = m * (m - 1) // 2
        s_max = m * (2 * N - m - 1) // 2
        start_m = X * m + D * s_min
        end_m = X * m + D * s_max

        if D > 0:
            if start_m > end_m:
                start, end = end_m, start_m
            else:
                start, end = start_m, end_m
        else:
            if start_m < end_m:
                start, end = end_m, start_m
            else:
                start, end = start_m, end_m

        r = start % D_abs
        residue_intervals[r].append((start, end))

    total = 0
    for r in residue_intervals:
        intervals = residue_intervals[r]
        intervals.sort()
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last_start, last_end = merged[-1]
                current_start, current_end = interval
                if current_start <= last_end + D_abs:
                    new_start = last_start
                    new_end = max(last_end, current_end)
                    merged[-1] = (new_start, new_end)
                else:
                    merged.append((current_start, current_end))
        for (start, end) in merged:
            count = (end - start) // D_abs + 1
            total += count

    print(total)

