    for r in intervals:
        intervals_list = sorted(intervals[r], key=lambda x: x[0])
        merged = []
        for s, e in intervals_list:
            if not merged:
                merged.append([s, e])
            else:
                last_s, last_e = merged[-1]
                if s <= last_e:
                    new_s = last_s
                    new_e = max(last_e, e)
                    merged[-1] = [new_s, new_e]
                else:
                    merged.append([s, e])
        for s, e in merged:
            count = (e - s) // abs(D) + 1
            total += count
