from collections import defaultdict

MOD = 10**9 + 7

def main():
    n, k = map(int, sys.stdin.readline().split())
    if k % 2 != 0:
        print(0)
        return

    target = k // 2
    # We need to count the number of permutations where the sum of (p_i - i) for p_i > i is target
    # We'll use dynamic programming with dp[i][s] representing the number of ways to arrange the first i elements with sum s
    # For each step, we can choose to place the i-th element in any position j, and calculate the contribution to s

    # Initialize dp[0][0] = 1
    dp = [defaultdict(int) for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(1, n+1):
        current_dp = dp[i]
        prev_dp = dp[i-1]
        for s_prev, count in prev_dp.items():
            for j in range(1, n+1):
                # j is the position for the i-th element
                # i-th element is originally at position i
                # if j > i, contribution is j - i
                # else, contribution is 0
                contribution = max(0, j - i)
                s_new = s_prev + contribution
                current_dp[s_new] = (current_dp[s_new] + count) % MOD

    print(dp[n].get(target, 0) % MOD)

