def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    allowed = list(map(int, input[2:2+M]))

    cost = {
        1: 2,
        2: 5,
        3: 5,
        4: 4,
        5: 5,
        6: 6,
        7: 3,
        8: 7,
        9: 6
    }

    # Initialize DP array
    dp = [-1] * (N + 1)
    dp[0] = 0

    for i in range(1, N + 1):
        for d in allowed:
            c = cost[d]
            if i >= c and dp[i - c] != -1:
                if dp[i] < dp[i - c] + 1:
                    dp[i] = dp[i - c] + 1

    max_digits = dp[N]

    # Construct the largest number
    allowed_sorted = sorted(allowed, reverse=True)
    result = []
    remaining = N

    for i in range(max_digits):
        for d in allowed_sorted:
            c = cost[d]
            if c > remaining:
                continue
            if dp[remaining - c] == (max_digits - i - 1):
                result.append(str(d))
                remaining -= c
                break

    print(''.join(result))

