    recursion_stack = []
    found = False
    result = []

    def dfs(u):
        nonlocal found
        visited[u] = True
        recursion_stack.append(u)
        for v in adj[u]:
            if not visited[v]:
                if dfs(v):
                    return True
            elif v in recursion_stack:
                # Found a cycle
                cycle = recursion_stack[recursion_stack.index(v):] + [v]
                # Check if the number of edges between the cycle vertices is equal to the cycle length
                cycle_set = set(cycle)
                edge_count = 0
                for i in range(len(cycle)):
                    for j in range(len(cycle)):
                        if i != j:
                            if (cycle[i], cycle[j]) in edges_set:
                                edge_count += 1
                if edge_count == len(cycle):
                    # Valid cycle found
                    result.extend(cycle)
                    found = True
                    return True
        recursion_stack.pop()
        return False

    for u in range(1, N+1):
        if not visited[u]:
            if dfs(u):
                break

