    count_ones = [0] * (max_bit + 1)

    for a in A:
        for j in range(max_bit + 1):
            if a & (1 << j):
                count_ones[j] += 1

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit < 0:
            return 0
        max_sum = 0
        if tight:
            k_bit = (K >> bit) & 1
            for choice in [0, 1]:
                if choice > k_bit:
                    continue
                new_tight = tight and (choice == k_bit)
                if choice == 1:
                    contribution = (N - count_ones[bit]) * (1 << bit)
                else:
                    contribution = count_ones[bit] * (1 << bit)
                res = contribution + dfs(bit - 1, new_tight)
                if res > max_sum:
                    max_sum = res
        else:
            for choice in [0, 1]:
                new_tight = False
                if choice == 1:
                    contribution = (N - count_ones[bit]) * (1 << bit)
                else:
                    contribution = count_ones[bit] * (1 << bit)
                res = contribution + dfs(bit - 1, new_tight)
                if res > max_sum:
                    max_sum = res
        return max_sum

    result = dfs(max_bit, True)
