    size_rows = [1] * N

    def find_rows(u):
        while parent_rows[u] != u:
            parent_rows[u] = parent_rows[parent_rows[u]]
            u = parent_rows[u]
        return u

    def union_rows(u, v):
        u_root = find_rows(u)
        v_root = find_rows(v)
        if u_root == v_root:
            return
        if size_rows[u_root] < size_rows[v_root]:
            u_root, v_root = v_root, u_root
        parent_rows[v_root] = u_root
        size_rows[u_root] += size_rows[v_root]

