from collections import deque

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1

    opponents = [[] for _ in range(N+1)]  # 1-based
    for i in range(1, N+1):
        for _ in range(N-1):
            opponents[i].append(int(input[idx]))
            idx += 1

    # Step 1: Generate all matches and assign unique IDs
    match_id = {}
    current_id = 0
    for i in range(1, N+1):
        for j in opponents[i]:
            u = min(i, j)
            v = max(i, j)
            if (u, v) not in match_id:
                match_id[(u, v)] = current_id
                current_id += 1

    # Step 2: For each player, generate list of match IDs in order
    player_matches = [[] for _ in range(N+1)]
    for i in range(1, N+1):
        for j in opponents[i]:
            u = min(i, j)
            v = max(i, j)
            mid = match_id[(u, v)]
            player_matches[i].append(mid)

    # Step 3: Build adjacency list and in-degree array
    adj = [[] for _ in range(current_id)]
    in_degree = [0] * current_id
    for i in range(1, N+1):
        for k in range(len(player_matches[i]) - 1):
            prev = player_matches[i][k]
            curr = player_matches[i][k+1]
            adj[prev].append(curr)
            in_degree[curr] += 1

    # Step 4: Kahn's algorithm for topological sort
    queue = deque()
    for i in range(current_id):
        if in_degree[i] == 0:
            queue.append(i)
    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != current_id:
        print(-1)
        return

    # Step 5: Compute longest path
    dist = [1] * current_id
    for u in top_order:
        for v in adj[u]:
            if dist[v] < dist[u] + 1:
                dist[v] = dist[u] + 1

    print(max(dist))

