def get_bits(n):
    if n == 0:
        return [0]
    bits = []
    while n > 0:
        bits.append(n & 1)
        n >>= 1
    bits.reverse()
    return bits

def compute_sum(n):
    if n == 0:
        return 2
    bits = get_bits(n)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(pos, tight, started):
        if pos == len(bits):
            if started:
                return 1
            else:
                return 2
        limit = bits[pos] if tight else 1
        total = 0
        for bit in range(0, limit + 1):
            new_tight = tight and (bit == limit)
            new_started = started or (bit == 1)
            if not new_started:
                contribution = 1
            else:
                if bit == 0:
                    contribution = 2
                else:
                    contribution = 1
            total += contribution * dp(pos + 1, new_tight, new_started)
        return total
    return dp(0, True, False)

