def get_zero_bits(x):
    bits = []
    for i in range(60):
        if not (x & (1 << i)):
            bits.append(i)
    return bits

def count_subsets(bits, K):
    bits.sort()
    n = len(bits)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(pos, current_val):
        if pos == n:
            return 1 if current_val <= K else 0
        res = dfs(pos + 1, current_val)
        new_val = current_val + (1 << bits[pos])
        if new_val <= K:
            res += dfs(pos + 1, new_val)
        return res
    return dfs(0, 0)

def main():
    import sys
    input = sys.stdin.read
    L, R = map(int, input().split())
    total = 0
    for x in range(L, R + 1):
        zero_bits = get_zero_bits(x)
        K = R - x
        actual_K = min(x - 1, K)
        count = count_subsets(zero_bits, actual_K)
        total += count
    print(total % MOD)

