def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    S = data[1]

    # Precompute suffix counts for R, G, B
    suffix_r = [0] * (N + 1)
    suffix_g = [0] * (N + 1)
    suffix_b = [0] * (N + 1)

    for j in range(N-1, -1, -1):
        suffix_r[j] = suffix_r[j+1] + (1 if S[j] == 'R' else 0)
        suffix_g[j] = suffix_g[j+1] + (1 if S[j] == 'G' else 0)
        suffix_b[j] = suffix_b[j+1] + (1 if S[j] == 'B' else 0)

    total_part1 = 0
    for i in range(N):
        for j in range(i+1, N):
            if S[i] != S[j]:
                # Find third color
                if S[i] == 'R' and S[j] == 'G':
                    third = 'B'
                elif S[i] == 'R' and S[j] == 'B':
                    third = 'G'
                elif S[i] == 'G' and S[j] == 'R':
                    third = 'B'
                elif S[i] == 'G' and S[j] == 'B':
                    third = 'R'
                elif S[i] == 'B' and S[j] == 'R':
                    third = 'G'
                elif S[i] == 'B' and S[j] == 'G':
                    third = 'R'
                else:
                    third = None
                if third:
                    count = suffix_r[j] + suffix_g[j] + suffix_b[j] - (suffix_r[j] if S[j] == 'R' else (suffix_g[j] if S[j] == 'G' else suffix_b[j])) - (suffix_r[j] if S[i] == 'R' else (suffix_g[j] if S[i] == 'G' else suffix_b[j]))
                    # Wait, this is not correct. Need to compute the count of third color
                    if third == 'R':
                        count = suffix_r[j]
                    elif third == 'G':
                        count = suffix_g[j]
                    else:
                        count = suffix_b[j]
            else:
                # S[i] == S[j], so k must be different from S[i]
                total_suffix = suffix_r[j] + suffix_g[j] + suffix_b[j]
                count = total_suffix - (suffix_r[j] if S[i] == 'R' else (suffix_g[j] if S[i] == 'G' else suffix_b[j]))
            total_part1 += count

    # Now compute count_part2: triplets in arithmetic progression with all different colors
    count_part2 = 0
    for j in range(N):
        for i in range(j):
            k = 2 * j - i
            if k >= N:
                continue
            if k <= j:
                continue
            if S[i] != S[j] and S[j] != S[k] and S[i] != S[k]:
                count_part2 += 1

    answer = total_part1 - count_part2
    print(answer)

