def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    S = input[1] if len(input) > 1 else ""

    prefix_r = [0] * (N + 1)
    prefix_g = [0] * (N + 1)
    prefix_b = [0] * (N + 1)

    for i in range(N):
        prefix_r[i+1] = prefix_r[i] + (1 if S[i] == 'R' else 0)
        prefix_g[i+1] = prefix_g[i] + (1 if S[i] == 'G' else 0)
        prefix_b[i+1] = prefix_b[i] + (1 if S[i] == 'B' else 0)

    total_valid = 0
    for i in range(N):
        for k in range(i+1, N):
            if S[i] != S[k]:
                # Calculate count_Si
                if S[i] == 'R':
                    count_Si = prefix_r[k] - prefix_r[i+1]
                elif S[i] == 'G':
                    count_Si = prefix_g[k] - prefix_g[i+1]
                else:
                    count_Si = prefix_b[k] - prefix_b[i+1]
                # Calculate count_Sk
                if S[k] == 'R':
                    count_Sk = prefix_r[k] - prefix_r[i+1]
                elif S[k] == 'G':
                    count_Sk = prefix_g[k] - prefix_g[i+1]
                else:
                    count_Sk = prefix_b[k] - prefix_b[i+1]
                total_valid += (k - i - 1) - (count_Si + count_Sk)

    invalid_triplets = 0
    for j in range(N):
        for i in range(j):
            k = 2 * j - i
            if k < N:
                if S[i] != S[j] and S[j] != S[k] and S[i] != S[k]:
                    invalid_triplets += 1

    print(total_valid - invalid_triplets)

