def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M_a = int(input[idx]); idx += 1
    M_b = int(input[idx]); idx += 1

    packages = []
    sum_a_total = 0
    sum_b_total = 0
    for _ in range(N):
        a = int(input[idx]); idx += 1
        b = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1
        packages.append((a, b, c))
        sum_a_total += a
        sum_b_total += b

    x_max = min(sum_a_total // M_a, sum_b_total // M_b)
    if x_max == 0:
        print(-1)
        return

    INF = float('inf')
    max_a = sum_a_total
    max_b = sum_b_total
    dp = [[INF] * (max_b + 1) for _ in range(max_a + 1)]
    dp[0][0] = 0

    for a_i, b_i, c_i in packages:
        for a in range(max_a, -1, -1):
            for b in range(max_b, -1, -1):
                if dp[a][b] != INF:
                    new_a = a + a_i
                    new_b = b + b_i
                    if new_a <= max_a and new_b <= max_b:
                        if dp[new_a][new_b] > dp[a][b] + c_i:
                            dp[new_a][new_b] = dp[a][b] + c_i

    min_cost = INF
    for x in range(1, x_max + 1):
        target_a = x * M_a
        target_b = x * M_b
        if dp[target_a][target_b] < min_cost:
            min_cost = dp[target_a][target_b]

    print(-1 if min_cost == INF else min_cost)

