    N = int(input[idx]); idx += 1
    M_a = int(input[idx]); idx += 1
    M_b = int(input[idx]); idx += 1
    packages = []
    for _ in range(N):
        a = int(input[idx]); idx += 1
        b = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1
        packages.append((a, b, c))

    d_list = [a * M_b - b * M_a for a, b, c in packages]
    mid = N // 2
    left = d_list[:mid]
    right = d_list[mid:]

    # Generate left_dict
    left_dict = {}
    k = len(left)
    for mask in range(1 << k):
        sum_d = 0
        sum_c = 0
        count = 0
        for i in range(k):
            if mask & (1 << i):
                sum_d += left[i]
                sum_c += packages[i][2]
                count += 1
        if sum_d in left_dict:
            current_cost, current_count = left_dict[sum_d]
            if sum_c < current_cost:
                left_dict[sum_d] = (sum_c, count)
            elif sum_c == current_cost:
                if count < current_count:
                    left_dict[sum_d] = (sum_c, count)
        else:
            left_dict[sum_d] = (sum_c, count)

    # Generate right_dict
    right_dict = {}
    m = len(right)
    for mask in range(1 << m):
        sum_d = 0
        sum_c = 0
        count = 0
        for i in range(m):
            if mask & (1 << i):
                sum_d += right[i]
                sum_c += packages[mid + i][2]
                count += 1
        if sum_d in right_dict:
            current_cost, current_count = right_dict[sum_d]
            if sum_c < current_cost:
                right_dict[sum_d] = (sum_c, count)
            elif sum_c == current_cost:
                if count < current_count:
                    right_dict[sum_d] = (sum_c, count)
        else:
            right_dict[sum_d] = (sum_c, count)

    min_cost = float('inf')
    for s in left_dict:
        target = -s
        if target in right_dict:
            left_cost, left_count = left_dict[s]
            right_cost, right_count = right_dict[target]
            total_cost = left_cost + right_cost
            total_count = left_count + right_count
            if total_count >= 1 and total_cost < min_cost:
                min_cost = total_cost

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

