        c = int(input[idx]); idx +=1
        elements.append( (a, b, c) )
    mid = N // 2
    left = elements[:mid]
    right = elements[mid:]

    def generate_subsets(elements, M_a, M_b):
        n = len(elements)
        subsets = {}
        for mask in range(1, 1 << n):
            sum_a = 0
            sum_b = 0
            cost = 0
            for i in range(n):
                if mask & (1 << i):
                    sum_a += elements[i][0]
                    sum_b += elements[i][1]
                    cost += elements[i][2]
            key = sum_a * M_b - sum_b * M_a
            if key in subsets:
                if cost < subsets[key]:
                    subsets[key] = cost
            else:
                subsets[key] = cost
        return subsets

    left_dict = generate_subsets(left, M_a, M_b)
    right_dict = generate_subsets(right, M_a, M_b)

    min_cost = float('inf')
