        min_cost = min(min_cost, left_dict[0])
    if 0 in right_dict:
        min_cost = min(min_cost, right_dict[0])

    for key in left_dict:
        target = -key
        if target in right_dict:
            total = left_dict[key] + right_dict[target]
            if total < min_cost:
                min_cost = total

    print(-1 if min_cost == float('inf') else min_cost)

