        count = [0] * c
        for i in range(n):
            for j in range(n):
                original_color = grid[i][j] - 1
                if (i + j) % 3 == group:
                    count[original_color] += 1
        cost = [0] * c
        for k in range(c):
            total = 0
            for color in range(c):
                total += count[color] * d[color][k]
            cost[k] = total
        group_costs.append(cost)

    min_total = float('inf')
    for c0 in range(c):
        for c1 in range(c):
            if c1 == c0:
                continue
            for c2 in range(c):
                if c2 == c0 or c2 == c1:
                    continue
                total = group_costs[0][c0] + group_costs[1][c1] + group_costs[2][c2]
                if total < min_total:
                    min_total = total
    print(min_total)

