def generate_configurations(W):
    configurations = []
    for num in range(0, 1 << (W-1)):
        valid = True
        for i in range(W-2):
            if (num >> i) & 1 and (num >> (i+1)) & 1:
                valid = False
                break
        if valid:
            config = []
            for i in range(W-1):
                if (num >> i) & 1:
                    config.append(i+1)
            configurations.append(config)
    return configurations

def main():
    import sys
    input = sys.stdin.read
    H, W, K = map(int, input().split())
    configurations = generate_configurations(W)

    dp = [[0]*(W+1) for _ in range(H+1)]
    dp[0][1] = 1

    for h in range(1, H+1):
        current_dp = [0]*(W+1)
        for config in configurations:
            for prev_pos in range(1, W+1):
                new_pos = prev_pos
                for line in config:
                    if line == prev_pos:
                        new_pos = line + 1
                    elif line + 1 == prev_pos:
                        new_pos = line
                current_dp[new_pos] = (current_dp[new_pos] + dp[h-1][prev_pos]) % MOD
        dp[h] = current_dp

    print(dp[H][K] % MOD)

