        total_layers[l] = 2 * total_layers[l - 1] + 3
        total_patties[l] = 2 * total_patties[l - 1] + 1

    def count_patties(L, X):
        if L == 0:
            return 1 if X >= 1 else 0
        T = total_layers[L - 1]
        if X == 0:
            return 0
        elif X == 1:
            return 0
        elif X <= 1 + T:
            return count_patties(L - 1, X - 1)
        elif X == 2 + T:
            return total_patties[L - 1] + 1
        else:
            a = X - (2 + T)
            if a <= T:
                return total_patties[L - 1] + 1 + count_patties(L - 1, a)
            else:
                return total_patties[L - 1] + 1 + total_patties[L - 1]

