def main():
    n = int(sys.stdin.readline())
    a = []
    for _ in range(n):
        a.append(list(map(int, sys.stdin.readline().split())))

    # Run Floyd-Warshall algorithm to check if the matrix is valid
    dist = [row[:] for row in a]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Check if the original matrix is the same as the computed shortest paths
    for i in range(n):
        for j in range(n):
            if dist[i][j] != a[i][j]:
                print(-1)
                return

    # Calculate the minimal total length of roads
    total = 0
    for u in range(n):
        for v in range(u + 1, n):
            found = False
            for w in range(n):
                if w == u or w == v:
                    continue
                if a[u][w] + a[w][v] == a[u][v]:
                    found = True
                    break
            if not found:
                total += a[u][v]

    print(total)

