    idx += 1
    W = int(input[idx])
    idx += 1

    items = []
    for _ in range(N):
        w = int(input[idx])
        idx += 1
        v = int(input[idx])
        idx += 1
        items.append((w, v))

    w0 = items[0][0]
    group0 = [v for w, v in items if w == w0]
    group1 = [v for w, v in items if w == w0 + 1]
    group2 = [v for w, v in items if w == w0 + 2]
    group3 = [v for w, v in items if w == w0 + 3]

    def compute_prefix(arr):
        prefix = [0]
        for v in arr:
            prefix.append(prefix[-1] + v)
        return prefix

    group0_sorted = sorted(group0, reverse=True)
    group1_sorted = sorted(group1, reverse=True)
    group2_sorted = sorted(group2, reverse=True)
    group3_sorted = sorted(group3, reverse=True)

    group0_prefix = compute_prefix(group0_sorted)
    group1_prefix = compute_prefix(group1_sorted)
    group2_prefix = compute_prefix(group2_sorted)
    group3_prefix = compute_prefix(group3_sorted)

    INF = float('-inf')
    max_n = N
    max_s = 3 * N
    dp = [[INF] * (max_s + 1) for _ in range(max_n + 1)]
    dp[0][0] = 0

    groups = [group1_sorted, group2_sorted, group3_sorted]
    contributions = [1, 2, 3]
    prefixes = [group1_prefix, group2_prefix, group3_prefix]

    for i in range(3):
        group = groups[i]
        contribution = contributions[i]
        prefix = prefixes[i]
        max_t = len(group)
        for t in range(1, max_t + 1):
            for m in range(max_n, -1, -1):
                for s in range(max_s, -1, -1):
                    if dp[m][s] != INF:
                        new_m = m + t
                        new_s = s + t * contribution
                        if new_m <= max_n and new_s <= max_s:
                            if dp[new_m][new_s] < dp[m][s] + prefix[t]:
                                dp[new_m][new_s] = dp[m][s] + prefix[t]

    max_total = 0
    for K in range(0, N + 1):
        S_max = W - w0 * K
        if S_max < 0:
            continue
        current_max = 0
        for m in range(0, K + 1):
            max_s_for_this_k = min(S_max, 3 * K)
            for s in range(0, max_s_for_this_k + 1):
                if dp[m][s] != INF and (K - m) <= len(group0_sorted):
                    val = dp[m][s] + group0_prefix[K - m]
                    if val > current_max:
                        current_max = val
        if current_max > max_total:
            max_total = current_max

    print(max_total)

