def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    A = list(map(int, input[2:2+N]))
    A.sort()
    pos_start = bisect.bisect_left(A, 0)
    neg_end = pos_start - 1

    def count_pairs(X):
        n = len(A)
        count = 0
        for i in range(n):
            if i == n - 1:
                break
            if A[i] == 0:
                if X >= 0:
                    count += (n - i - 1)
                continue
            if A[i] > 0:
                left, right = i + 1, n - 1
                res = i
                while left <= right:
                    mid = (left + right) // 2
                    if A[i] * A[mid] <= X:
                        res = mid
                        left = mid + 1
                    else:
                        right = mid - 1
                count += (res - i)
            else:
                if X >= 0:
                    left_neg, right_neg = i + 1, neg_end
                    if left_neg <= right_neg:
                        res_neg = i
                        while left_neg <= right_neg:
                            mid = (left_neg + right_neg) // 2
                            if A[i] * A[mid] <= X:
                                res_neg = mid
                                left_neg = mid + 1
                            else:
                                right_neg = mid - 1
                        count += (res_neg - i)
                    start_pos = max(pos_start, i + 1)
                    if start_pos <= n - 1:
                        count += (n - 1 - start_pos + 1)
                else:
                    threshold = X / A[i]
                    start_pos = max(pos_start, i + 1)
                    if start_pos <= n - 1:
                        left, right = start_pos, n - 1
                        res_pos = n
                        while left <= right:
                            mid = (left + right) // 2
                            if A[mid] >= threshold:
                                res_pos = mid
                                right = mid - 1
                            else:
                                left = mid + 1
                        count += (n - res_pos)
        return count

    low = -10**18
    high = 10**18
    answer = 0
    while low <= high:
        mid = (low + high) // 2
        cnt = count_pairs(mid)
        if cnt >= K:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1
    print(answer)

