    A = list(map(int, input[2:2+N]))
    A.sort()

    negatives = []
    zeros = []
    positives = []
    for num in A:
        if num < 0:
            negatives.append(num)
        elif num == 0:
            zeros.append(num)
        else:
            positives.append(num)

    m = len(negatives)
    z = len(zeros)
    p = len(positives)

