        if X < 0:
            count_neg_pos = 0
            for a in negatives:
                threshold = X / a
                idx = bisect.bisect_left(positives, threshold)
                count_neg_pos += len(positives) - idx
            return count_neg_pos
        else:
            count_neg_neg = 0
            for i in range(len(negatives)):
                left = i + 1
                right = len(negatives) - 1
                res = i
