    A = list(map(int, input[2:2+N]))
    A.sort()

    # Precompute split and pos_split
    split = bisect.bisect_left(A, 0)
    pos_split = bisect.bisect_right(A, 0)

    def count_pairs(X):
        count = 0
        for i in range(N):
            if A[i] == 0:
                if X >= 0:
                    count += (N - i - 1)
                continue
            if A[i] > 0:
                if X < 0:
                    continue
                left = i + 1
                right = N - 1
                best = i
                while left <= right:
                    mid = (left + right) // 2
                    if A[i] * A[mid] <= X:
                        best = mid
                        left = mid + 1
                    else:
                        right = mid - 1
                count += (best - i)
            else:
                if X < 0:
                    if i + 1 > pos_split:
                        count_pos = 0
                    else:
                        count_pos = N - pos_split
                    count += count_pos
                else:
                    # count_zero_or_pos
                    if i + 1 > split:
                        count_zero_or_pos = N - (i + 1)
                    else:
                        count_zero_or_pos = N - split
                    # count_neg_part
                    left = i + 1
                    right = split - 1
                    best_neg = i
                    if left <= right:
                        while left <= right:
                            mid = (left + right) // 2
                            if A[i] * A[mid] <= X:
                                best_neg = mid
                                left = mid + 1
                            else:
                                right = mid - 1
                        count_neg_part = best_neg - i
                        count += count_neg_part
                    count += count_zero_or_pos
        return count

