def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    if N == 0:
        print("not coprime")
        return

    max_A = max(A)

    # Handle case where all elements are 1
    if max_A == 1:
        print("pairwise coprime")
        return

    # Build SPF sieve
    spf = list(range(max_A + 1))
    for i in range(2, int(max_A**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, max_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Now, for each number in A, collect primes
    prime_count = {}
    for num in A:
        if num == 1:
            continue
        x = num
        primes = set()
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            if p in prime_count:
                prime_count[p] += 1
            else:
                prime_count[p] = 1

    # Check if any prime occurs in more than one number
    pairwise = True
    for count in prime_count.values():
        if count >= 2:
            pairwise = False
            break

    if pairwise:
        print("pairwise coprime")
        return

    # Compute overall GCD
    overall_gcd = A[0]
    for num in A[1:]:
        overall_gcd = math.gcd(overall_gcd, num)
        if overall_gcd == 1:
            break

    if overall_gcd == 1:
        print("setwise coprime")
    else:
        print("not coprime")

