from collections import deque

def main():
    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx]); idx +=1
    W = int(input[idx]); idx +=1
    K = int(input[idx]); idx +=1
    x1 = int(input[idx]); idx +=1
    y1 = int(input[idx]); idx +=1
    x2 = int(input[idx]); idx +=1
    y2 = int(input[idx]); idx +=1

    grid = []
    for _ in range(H):
        row = input[idx]
        grid.append(row)
        idx +=1

    # Preprocess east_steps, west_steps, north_steps, south_steps
    east_steps = [[0]*(W+2) for _ in range(H+2)]
    west_steps = [[0]*(W+2) for _ in range(H+2)]
    north_steps = [[0]*(W+2) for _ in range(H+2)]
    south_steps = [[0]*(W+2) for _ in range(H+2)]

    # Compute east_steps
    for i in range(1, H+1):
        for j in range(W, 0, -1):
            if grid[i-1][j-1] == '@':
                east_steps[i][j] = 0
            else:
                if j == W:
                    east_steps[i][j] = 1
                else:
                    east_steps[i][j] = 1 + east_steps[i][j+1]

    # Compute west_steps
    for i in range(1, H+1):
        for j in range(1, W+1):
            if grid[i-1][j-1] == '@':
                west_steps[i][j] = 0
            else:
                if j == 1:
                    west_steps[i][j] = 1
                else:
                    west_steps[i][j] = 1 + west_steps[i][j-1]

    # Compute north_steps
    for j in range(1, W+1):
        for i in range(1, H+1):
            if grid[i-1][j-1] == '@':
                north_steps[i][j] = 0
            else:
                if i == 1:
                    north_steps[i][j] = 1
                else:
                    north_steps[i][j] = 1 + north_steps[i-1][j]

    # Compute south_steps
    for j in range(1, W+1):
        for i in range(H, 0, -1):
            if grid[i-1][j-1] == '@':
                south_steps[i][j] = 0
            else:
                if i == H:
                    south_steps[i][j] = 1
                else:
                    south_steps[i][j] = 1 + south_steps[i+1][j]

    # BFS
    visited = [[False]*(W+2) for _ in range(H+2)]
    q = deque()
    q.append( (x1, y1) )
    visited[x1][y1] = True
    dist = [[0]*(W+2) for _ in range(H+2)]
    dist[x1][y1] = 0

    directions = [ (0, 1), (0, -1), (-1, 0), (1, 0) ]  # east, west, north, south

    while q:
        i, j = q.popleft()
        if i == x2 and j == y2:
            print(dist[i][j])
            return
        # Check all four directions
        for d in range(4):
            di, dj = directions[d]
            # Compute max_steps for this direction
            if d == 0:  # east
                max_steps = east_steps[i][j] - 1
            elif d == 1:  # west
                max_steps = west_steps[i][j] - 1
            elif d == 2:  # north
                max_steps = north_steps[i][j] - 1
            else:  # south
                max_steps = south_steps[i][j] - 1

            if max_steps >= 1:
                # Add 1 step
                ni, nj = i + di * 1, j + dj * 1
                if 1 <= ni <= H and 1 <= nj <= W:
                    if not visited[ni][nj]:
                        visited[ni][nj] = True
                        dist[ni][nj] = dist[i][j] + 1
                        q.append( (ni, nj) )
                # Add K steps if possible
                if K >= 1 and max_steps >= K:
                    ni, nj = i + di * K, j + dj * K
                    if 1 <= ni <= H and 1 <= nj <= W:
                        if not visited[ni][nj]:
                            visited[ni][nj] = True
                            dist[ni][nj] = dist[i][j] + 1
                            q.append( (ni, nj) )

    print(-1)

