def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    B = list(map(int, data[N+1:2*N+1]))

    for i in range(N):
        if B[i] != A[i]:
            continue
        low = i + 1
        high = N - 1
        res = -1
        while low <= high:
            mid = (low + high) // 2
            if B[mid] > A[i]:
                res = mid
                high = mid - 1
            else:
                low = mid + 1
        if res == -1:
            print("No")
            return
        else:
            B[i], B[res] = B[res], B[i]

    print("Yes")
    print(' '.join(map(str, B)))

