import bisect
import math

def log_comb(n, k):
    if k < 0 or k > n:
        return -float('inf')
    def log_fact(x):
        if x == 0:
            return 0.0
        return x * math.log(x) - x + 0.5 * math.log(2 * math.pi * x)
    return log_fact(n) - log_fact(k) - log_fact(n - k)

