    best_i = None
    best_j = None
    for i in range(n):
        current = a_sorted[i]
        target = current / 2
        pos = bisect.bisect_left(a_sorted, target, 0, i)
        candidates = []
        if pos > 0:
            candidates.append(a_sorted[pos-1])
        if pos < i:
            candidates.append(a_sorted[pos])
