def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    S = list(map(int, input[ptr:ptr+N]))
    ptr += N
    T = list(map(int, input[ptr:ptr+N]))
    ptr += N
    U = list(map(int, input[ptr:ptr+N]))
    ptr += N
    V = list(map(int, input[ptr:ptr+N]))
    ptr += N

    a = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if S[i] == 0 and T[j] == 0:
                a[i][j] = U[i] | V[j]
            elif S[i] == 0 and T[j] == 1:
                a[i][j] = U[i]
            elif S[i] == 1 and T[j] == 0:
                a[i][j] = V[j]
            else:
                a[i][j] = U[i] & V[j]

    valid = True
    # Check rows
    for i in range(N):
        if S[i] == 0:
            row_and = a[i][0]
            for j in range(1, N):
                row_and &= a[i][j]
            if row_and != U[i]:
                valid = False
        else:
            row_or = a[i][0]
            for j in range(1, N):
                row_or |= a[i][j]
            if row_or != U[i]:
                valid = False
    if not valid:
        print(-1)
        return

    # Check columns
    for j in range(N):
        if T[j] == 0:
            col_and = a[0][j]
            for i in range(1, N):
                col_and &= a[i][j]
            if col_and != V[j]:
                valid = False
        else:
            col_or = a[0][j]
            for i in range(1, N):
                col_or |= a[i][j]
            if col_or != V[j]:
                valid = False
    if valid:
        for row in a:
            print(' '.join(map(str, row)))
    else:
        print(-1)

